
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_blyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_blyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.190297652444016e+00, -4.108082567907291e+00, -3.992925164597093e+00, -3.833496046822785e+00, -3.616436691829473e+00, -3.327894008295729e+00, -2.957102246926313e+00, -2.502600380050762e+00, -1.979654341245294e+00, -1.421650988316495e+00, -8.771854244819220e-01, -5.573923612391735e-01, -4.662083162719955e-01, -3.562261872873001e-01, -2.087890931631494e-01, -7.121080772872203e-02, -3.960132145045538e-03, -1.111063768945444e-03, -7.528057565810435e-05, -1.750696568227364e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


